package app.thawani

internal fun cards4(): List<Card> = listOf(
Card("p19","kids_elderly","فقدان طفل في الأماكن المزدحمة","911","استجابة فورية — الدقائق العشر الأولى حاسمة","c","لا تبحث في صمت؛ ابدأ فوراً بـ (البحث بصوت عالٍ بالوصف وليس الاسم فقط): اذكر عمر الطفل ولون ملابسه بصوت مسموع ليلتفت كل من حولك خلال ثوانٍ.",listOf("توقف في مكانك لثوانٍ ونادِ بصوت مرتفع بوصف الطفل: (أبحث عن طفل عمره 5 سنوات يرتدي قميصاً أحمر!) فهذا يجعل جميع المتواجدين حولك عيوناً تبحث معك فوراً.","أبلغ أقرب رجل أمن في المركز أو الساحة فوراً لإغلاق أو مراقبة البوابات والمخارج الرئيسية.","ابقَ أنت (أو أحد الوالدين) في آخر نقطة شوهد فيها الطفل تماماً، لأن الأطفال غالباً يعودون لنفس النقطة.","تفقد فوراً الأماكن الخطرة أو الجاذبة القريبة (المصاعد، السلالم الكهربائية، دورات المياه، محلات الألعاب، أو نوافير المياه).","اتصل بـ 911 وشارك أحدث صورة للطفل (التقط صورة لطفلك بجوالك قبل دخول الأماكن المزدحمة لتوثيق ملابسه في ذلك اليوم)."),listOf("لا تشعر بالحرج من رفع صوتك بوصف الطفل في اللحظة الأولى.","لا يغادر جميع أفراد الأسرة نقطة الاختفاء معاً؛ يجب بقاء شخص ثابت في نفس المكان."),listOf("وضع سوار تعريفي أو بطاقة في جيب الطفل تحتوي على رقم جوال الأب والأم."),listOf("البيت","المدرسة","الاستراحة","السفر"),listOf(Link("المنصة الوطنية: أرقام الطوارئ","https://my.gov.sa/saml.authn/emergency-contact")),listOf()),
Card("p20","home_safety","تسرب الغاز المنزلي (LPG)","998","خطر انفجار واشتعال — إخلاء وتأمين فوري","w","عند شم رائحة غاز: لا تلمس أي مفتاح كهرباء (لا تشغّل ولا تطفئ أي زر إضاءة أو مروحة شفط) لأن الشرارة الداخلية الصغيرة كفيلة بإحداث انفجار.",listOf("أغلق صمام أسطوانة الغاز الرئيسي ومفاتيح الموقد فوراً إذا كان الوصول إليها آمناً.","افتح جميع النوافذ والأبواب الخارجية بهدوء لتهوية المنزل وتشتيت الغاز المتجمع بالقرب من الأرض.","أخلِ جميع أفراد الأسرة إلى خارج المنزل فوراً (استخدم الدرج وتجنب المصعد تماماً).","افصل الكهرباء من القاطع الرئيسي الخارجي فقط إذا كان لوح القواطع خارج المنزل وبعيداً عن منطقة التسرب.","بعد الخروج لمكان آمن، اتصل بالدفاع المدني على الرقم 998 إذا استمر التسرب."),listOf("لا تشغّل مروحة الشفط أو تطفئ الأنوار أو تسحب أي فيش كهربائي داخل المنطقة المشتبه بتسرب الغاز فيها.","لا تختبر مكان تسرب الغاز باستخدام ولاعة أو عود ثقاب أبداً."),listOf("تركيب كاشف تسرب الغاز الذكي في المطبخ بالقرب من مستوى الأرض (لأن غاز الطبخ أثقل من الهواء)."),listOf("البيت","الاستراحة"),listOf(Link("وزارة الصحة: التعامل مع السموم والغازات","https://www.moh.gov.sa/healthawareness/educationalcontent/firstaid/pages/018.aspx")),listOf()),
Card("p21","home_safety","حرائق المطبخ والزيوت والكهرباء (قاعدة PASS)","998","خطر امتداد النيران والدخان — تدخل أو إخلاء فوري","c","لا تسكب الماء أبداً على مقلاة الزيت المشتعلة؛ فالماء يتبخر لحظياً وينثر كرات النار المشتعلة في أنحاء المطبخ.",listOf("في حريق مقلاة الزيت: أطفئ مصدر الغاز/الكهرباء فوراً، وغطِّ المقلاة ببطانية حريق أو غطاء معدني محكم لكتم الأكسجين، واتركها حتى تبرد تماماً.","في حريق جهاز كهربائي: افصل التيار من القاطع الرئيسي أولاً، ثم استخدم طفاية البودرة الجافة (ABC) أو ثاني أكسيد الكربون (CO2).","لاستخدام طفاية الحريق طبّق قاعدة (PASS): اسحب مسمار الأمان، وجّه الخرطوم لقاعدة اللهب، اضغط المكبس، وحرّك يميناً ويساراً.","إذا كان الحريق كبيراً أو يتصاعد منه دخان كثيف: أغلق باب الغرفة المشتعلة خلفك لحصر النار وأخلِ المنزل فوراً.","عند الخروج وسط الدخان: انخفض قريباً من الأرض وغطِّ أنفك وفمك بقماش مبلل، ثم اتصل بالدفاع المدني (998)."),listOf("لا تحمل مقلاة الزيت المشتعلة وتمشِ بها نحو الحوض أو الخارج لأن الزيت المشتعل سينسكب عليك.","لا تستخدم المصعد الكهربائي أثناء الحريق تحت أي ظرف."),listOf("توفير طفاية حريق بودرة (4 أو 6 كجم) وبطانية حريق في مدخل المطبخ بمكان ظاهر."),listOf("البيت","المدرسة","الاستراحة","التخييم","السفر"),listOf(Link("الدفاع المدني السعودي: السلامة والإنذار","https://998.gov.sa/")),listOf()),
Card("p22","home_safety","الصعق الكهربائي","997","حرج — لا تلمس المصاب قبل فصل التيار","d","لا تلمس المصاب المتصل بالتيار الكهربائي بيديك المجردتين أبداً حتى لا تصبح ضحية ثانية؛ افصل القاطع الكهربائي أولاً.",listOf("افصل مصدر التيار الكهربائي فوراً من القاطع الرئيسي (الطبلون) أو بنزع القابس إذا كان آمناً.","إذا تعذر فصل التيار فوراً: قف على سطح جاف عازل (خشب أو مطاط) واستخدم عصا خشبية جافة أو كرسياً بلاستيكياً لإبعاد السلك عن المصاب.","بمجرد ابتعاد المصاب عن التيار: افحص وعيه وتنفسه فوراً؛ فالصعق الكهربائي قد يسبب رجفاناً وتوقفاً مفاجئاً للقلب.","إذا كان لا يتنفس: اتصل بـ 997 وابدأ الإنعاش القلبي الرئوي (CPR) فوراً.","إذا كان واعياً ويتنفس: ابحث عن حروق الكهرباء (في نقطة الدخول والخروج) وغطِّها بشاش معقم جاف."),listOf("لا تقترب من أسلاك الضغط العالي الساقطة على الأرض أو الملامسة للمركبات أو تجمعات المياه.","لا تستخدم أي أداة معدنية أو مبللة لإبعاد المصاب عن مصدر الكهرباء."),listOf("التأكد من عمل قاطع الحماية من التسرب الأرضي (RCD / ELCB) في لوحة كهرباء المنزل."),listOf("البيت","الاستراحة","المدرسة"),listOf(Link("وزارة الصحة: الإصابات المنزلية","https://www.moh.gov.sa/awarenessplateform/firstaid/pages/homeinjuries.aspx")),listOf()),
Card("p23","home_safety","الاحتجاز داخل المصعد","998","سلامة المباني — التزام الهدوء ومنع الخروج العشوائي","t","المصعد المغلق يحتوي على فتحات تهوية كافية ولا ينفد منه الأكسجين؛ الخطر الأكبر هو محاولة فتح الباب عنوة والخروج بين الطوابق.",listOf("اضغط زر جرس الإنذار أو الهاتف الداخلي في المصعد، واتصل بالدفاع المدني (998) أو رقم صيانة المصعد المدون بالداخل.","اضغط على أزرار جميع الطوابق السفلية؛ فقد يتحرك المصعد تلقائياً لأقرب طابق ببطارية الطوارئ (ARD).","اجلس على أرضية المصعد أو اسند ظهرك للحائط للحفاظ على توازنك وتقليل التوتر ريثما يصل المختصون.","إذا كنت خارج المصعد: طمئن المحتجزين بالداخل، وتوجه لغرفة المحرك لفصل قاطع المصعد الرئيسي فقط إذا طُلب منك ذلك من الدفاع المدني.","اترك عملية الإنزال اليدوي وفتح الباب بالمفتاح المثلث لفني الصيانة المختص أو رجال الدفاع المدني."),listOf("لا تحاول أبداً فتح باب المصعد عنوة والقفز للخارج إذا كان المصعد متوقفاً بين طابقين.","لا تقفز داخل كابينة المصعد لمحاولة تحريكها لأن ذلك يفعل فرامل الأمان الميكانيكية."),listOf("تثبيت ملصق واضح داخل المصعد وخارجه يحتوي على رقم الدفاع المدني (998) ورقم طوارئ الصيانة."),listOf("البيت","الاستراحة","المدرسة"),listOf(),listOf()),
Card("p24","home_safety","خطة الإخلاء المنزلي العائلي السريع","911","تخطيط وقائي واستجابة سريعة للأسرة","p","اخرج أولاً ثم اتصل بالطوارئ من الخارج؛ لا تضيع الثواني الثمينة في جمع الممتلكات أو المقتنيات الثمينة.",listOf("عند سماع جرس الإنذار أو اكتشاف خطر: نادِ بصوت عالٍ وواضح لتنبيه جميع أفراد الأسرة فوراً.","تأكد من مرافقة الأطفال وكبار السن (حدد مسبقاً من هو المسؤول عن مساعدة كل طفل أو كبير سن في الأسرة).","قبل فتح أي باب داخلي: المس مقبض الباب وأعلى الباب بظهر يدك؛ إذا كان ساخناً لا تفتحه واسلك المخرج البديل.","أغلق الأبواب خلفك أثناء الخروج (دون قفلها بالمفتاح) لإبطاء انتشار الدخان والحريق بين الغرف.","اتجه مباشرة إلى (نقطة التجمع العائلية) المحددة خارج المبنى، وتفقد وجود الجميع بالاسم، ثم اتصل بـ 998 أو 911."),listOf("لا تعد إلى داخل المنزل المشتعل تحت أي ظرف.","لا تقفل أبواب المخارج الرئيسية بالمفتاح وتترك المفتاح في مكان بعيد ليلاً."),listOf("تحديد مخرجين لكل غرفة وإجراء تجربة إخلاء عائلية سريعة مرة كل 6 أشهر."),listOf("البيت","الاستراحة","المدرسة"),listOf(Link("الدفاع المدني السعودي: السلامة والإنذار","https://998.gov.sa/")),listOf())
)
